use vstd::prelude::*;

verus! {

// Helper specification function to define the toggle operation
spec fn toggle_char(c: char) -> char {
    if c.is_ascii_lowercase() {
        c.to_ascii_uppercase()
    } else if c.is_ascii_uppercase() {
        c.to_ascii_lowercase()
    } else {
        c
    }
}

fn to_toggle_case(str1: &Vec<char>) -> (result: Vec<char>)
    ensures
        result.len() == str1.len(),
        forall|i: int| 0 <= i < str1.len() ==> 
            result[i] == toggle_char(str1[i]),
{
    let mut result = Vec::new();
    let mut idx = 0;
    
    while idx < str1.len()
        invariant
            0 <= idx <= str1.len(),
            result.len() == idx,
            forall|i: int| 0 <= i < idx ==> 
                result[i] == toggle_char(str1[i]),
    {
        let c = str1[idx];
        let toggled = if c.is_ascii_lowercase() {
            c.to_ascii_uppercase()
        } else if c.is_ascii_uppercase() {
            c.to_ascii_lowercase()
        } else {
            c
        };
        
        result.push(toggled);
        idx += 1;
    }
    
    result
}

} // verus!